import{_ as i,a0 as a,w as l,s,ao as x,I as r,x as e,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse(`{"title":"對 Linux 內核的發展方向的展望 | LCTT x X-CMD","titleTemplate":false,"description":"對 Linux 內核的發展方向的展望 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"對 Linux 內核的發展方向的展望 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"對 Linux 內核的發展方向的展望 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150820 A Look at What's Next for the Linux Kernel","title":"對 Linux 內核的發展方向的展望","tag":"201509","desc":""},"relativePath":"201509/20150820 A Look at What's Next for the Linux Kernel.md","filePath":"[post].md"}`),u={name:"201509/20150820 A Look at What's Next for the Linux Kernel.md"};function L(m,t,f,d,T,C){const n=a("Link");return l(),s("div",null,[t[13]||(t[13]=x('<h1 id="對-linux-內核的發展方向的展望" tabindex="-1">對 Linux 內核的發展方向的展望 <a class="header-anchor" href="#對-linux-內核的發展方向的展望" aria-label="Permalink to “對 Linux 內核的發展方向的展望”">​</a></h1><p><img src="http://www.eweek.com/imagesvr_ce/485/290x195cilinux1.jpg" alt=""></p><p>** Linux 4.2 內核涉及到史上最多的貢獻者數量，內核開發者 Jonathan Corbet 如是説。**</p><p>西雅圖報道。Linux 內核持續增長：代碼量在增加，代碼貢獻者數量也在增加。而隨之而來的一些挑戰需要處理一下。以上是 Jonathan Corbet 在今年的 LinuxCon 的內核年度報告上提出的主要觀點。以下是他的主要演講內容：</p><p>Linux 4.2 內核已經於上月底釋出。Corbet 強調有 1569 名開發者為這個版本貢獻了代碼，其中 277 名是第一次提交代碼。</p><p>越來越多的開發者的加入，內核更新非常快，Corbet 估計現在大概 63 天就能產生一個新的內核里程碑。</p><p>Linux 4.2 涉及多方面的更新。其中一個就是引進了 OverLayFS，這是一種只讀型文件系統，它可以實現在一個容器之上再放一個容器。</p><p>網絡系統對小包傳輸性能也有了提升，這對於高頻金融交易而言非常重要。提升的方面主要集中在減小處理數據包的時間的能耗。</p><p>依然有新的驅動中加入內核。在每個內核發佈週期，平均會有 60 到 80 個新增或升級驅動中加入。</p><p>另一個主要更新是實時內核補丁，這個特性在 4.0 版首次引進，好處是系統管理員可以在生產環境中打上內核補丁而不需要重啓系統。當補丁所需要的元素都已準備就緒，打補丁的過程會在後台持續而穩定地進行。</p><p><strong>Linux 安全, IoT 和其他關注點</strong></p><p>過去一年中，安全問題在開源社區是一個很熱的話題，這都歸因於那些引發高度關注的事件，比如 Heartbleed 和 Shellshock。</p><p>“我毫不懷疑 Linux 代碼對這些方面的忽視會產生一些令人不悦的問題”，Corbet 原話。</p><p>他強調説過去 10 年間有超過 3 百萬行代碼不再被開發者修改，而產生 Shellshock 漏洞的代碼的年齡已經是 20 歲了，近年來更是無人問津。</p><p>另一個關注點是 2038 問題，Linux 界的“千年蟲”，如果不解決，2000 年出現過的問題還會重現。2038 問題説的是在 2038 年一些 Linux 和 Unix 機器會死機（LCTT譯註：32 位系統記錄的時間，在2038年1月19日星期二晚上03:14:07之後的下一秒，會變成負數）。Corbet 説現在離 2038 年還有 23 年時間，現在部署的系統都會考慮 2038 問題。</p><p>Linux 已經啓動一些初步的方案來修復 2038 問題了，但做的還遠遠不夠。“現在就要修復這個問題，而不是等 20 年後把這個頭疼的問題留給下一代解決，我們卻享受着退休的美好時光”。</p><p>物聯網(IoT)也是 Linux 關注的領域，Linux 是物聯網嵌入式操作系統的主要佔有者，然而這並沒有什麼卵用。Corget 認為日漸臃腫的內核對於未來的物聯網設備來説肯定過於龐大。</p><p>現在有一個項目就是做內核最小化的，獲取足夠的支持對於這個項目來説非常重要。</p><p>“除了 Linux 之外，也有其他項目可以做物聯網，但那些項目不會像 Linux 一樣開放”，Corbet 説，“我們不能指望 Linux 在物聯網領域一直保持優勢，我們需要靠自己的努力去做到這點，我們需要注意不能讓內核變得越來越臃腫。”</p><hr>',20)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.eweek.com/enterprise-apps/a-look-at-whats-next-for-the-linux-kernel.html"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.eweek.com/enterprise-apps/a-look-at-whats-next-for-the-linux-kernel.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),o(n,{href:"http://www.eweek.com/cp/bio/Sean-Michael-Kerner/"},{default:p(()=>[...t[2]||(t[2]=[e("Sean Michael Kerner",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),o(n,{href:"https://github.com/bazz2"},{default:p(()=>[...t[3]||(t[3]=[e("bazz2",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),o(n,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const b=i(u,[["render",L]]);export{k as __pageData,b as default};
